const $=id=>document.getElementById(id);let t=2,step=0,playing=false,last=null,raf;
const fmt=n=>Number(n.toFixed(2)).toString();const threeHalves='<span class="frac"><span>3</span><span>2</span></span>';
function geometry(x){return {p:x,qx:Math.min(3*x,12),qy:Math.max(0,3*x-12),height:Math.min(3*x,12),area:x*Math.min(3*x,12)/2}}
function lesson(){const pages=[
`<div class="eyebrow">STEP 01 · Qが上の辺にいる間</div><h2>底辺も高さも時間で変わる</h2><p>Pは毎秒1 cmだから <strong class="blue">AP＝x cm</strong>。<br>Qは毎秒3 cmだから <strong class="amber">AQ＝3x cm</strong>。APとAQは垂直だから、AQを高さにできるぞ。</p><div class="formula">y ＝ x × 3x ÷ 2 ＝ ${threeHalves}x²</div><p>QがDに着くのは <strong>12÷3＝4秒後</strong>。<br>だから、xの変域は <strong>0 ≦ x ≦ 4</strong> だ。</p>`,
`<div class="eyebrow">STEP 02 · Qが右の辺にいる間</div><h2>高さは12 cmで変わらない！</h2><p>底辺は引き続き <strong class="blue">AP＝x cm</strong>。<br>高さは、Qから<strong>直線APまでの垂直な距離</strong>だ。QがDC上なら、いつでも横の長さ<strong>12 cm</strong>になるぞ。</p><div class="formula">y ＝ x × 12 ÷ 2 ＝ 6x</div><p>Dに着くのは4秒後、Cに着くのは<br><strong>(12＋6)÷3＝6秒後</strong>。<br>だから、xの変域は <strong>4 ≦ x ≦ 6</strong> だ。</p><p class="note">DQの長さは高さではないぞ。高さの足がAPの延長上にあっても、この公式を使えるんだ。</p>`,
`<div class="eyebrow">STEP 03 · 式と変域を確認</div><h2>Qがいる辺で式を使い分けよう</h2><div class="formula">AD上：y＝${threeHalves}x²<br><small>0 ≦ x ≦ 4</small><br>DC上：y＝6x<br><small>4 ≦ x ≦ 6</small></div><p>4秒では、どちらの式でも<strong>24 cm²</strong>。<br>6秒では<strong>36 cm²</strong>で、長方形全体の面積の半分だ！</p><form id="quiz"><label for="answer">5秒後の面積は？</label><div class="buttons"><input id="answer" type="number" step="any" required aria-label="5秒後の面積"> <span>cm²</span><button class="primary" type="submit">確かめる</button></div></form><p id="feedback" class="feedback" aria-live="polite"></p>`];$('lesson').innerHTML=pages[step];if(step===2)$('quiz').onsubmit=e=>{e.preventDefault();const ok=Number($('answer').value)===30;$('feedback').textContent=ok?'正解だ！ QはDC上だから、6×5＝30 cm²だぞ。':'5秒は4秒から6秒の間。Qはどの辺にいるかな？';if(ok)setTime(5)}}
function render(){const g=geometry(t),py=65+40*g.p,qx=150+40*g.qx,qy=65+40*g.qy;const put=(id,attrs)=>Object.entries(attrs).forEach(([k,v])=>$(id).setAttribute(k,v));put('triangle',{points:`150,65 150,${py} ${qx},${qy}`});put('pDot',{cx:150,cy:py});put('qDot',{cx:qx,cy:qy});put('base',{x1:150,y1:65,x2:150,y2:py});put('height',{d:`M150 ${qy}H${qx}`});put('extension',{d:g.qy>g.p?`M150 ${py}V${qy}`:''});put('rightAngle',{d:t>0?`M150 ${qy+ (t<=4?12:-12)}h12v${t<=4?-12:12}`:''});put('pLabel',{x:112,y:py+7});put('qLabel',{x:qx+12,y:qy-12});$('pLabel').textContent=t===0?'':t===6?'P・B':'P';$('qLabel').textContent=t===0?'':t===4?'Q・D':t===6?'Q・C':'Q';$('aLabel').textContent=t===0?'A・P・Q':'A';$('bLabel').style.display=t===6?'none':'';$('cLabel').style.display=t===6?'none':'';$('dLabel').style.display=t===4?'none':'';put('heightLabel',{x:(150+qx)/2,y:qy+(t<=4?28:-16)});$('heightLabel').textContent=t===0?'':`高さ ${fmt(g.height)} cm`;put('baseLabel',{x:164,y:(65+py)/2+18});$('baseLabel').textContent=t>0?`AP ${fmt(t)} cm`:'';$('time').textContent=t.toFixed(1);$('slider').value=t;$('baseValue').textContent=fmt(t);$('heightValue').textContent=fmt(g.height);$('areaValue').textContent=fmt(g.area);$('location').textContent=t===4?'Qは点D：２つの場合の境目':t<=4?'Qは辺AD上':'Qは辺DC上';$('liveFormula').innerHTML=t<=4?`y＝${threeHalves}x²　（0 ≦ x ≦ 4）`:'y＝6x　（4 ≦ x ≦ 6）';const gx=45+55*t,gy=190-g.area*165/36;put('dot',{cx:gx,cy:gy});put('guide',{d:`M45 ${gy}H${gx}V190`})}
function stop(){playing=false;cancelAnimationFrame(raf);$('play').textContent='▶ 再生'}function setTime(n){stop();t=n;render()}function frame(now){if(!playing)return;if(last!==null)t=Math.min(6,t+(now-last)/1000);last=now;render();if(t>=6)stop();else raf=requestAnimationFrame(frame)}
$('slider').oninput=e=>setTime(Number(e.target.value));$('reset').onclick=()=>setTime(0);$('corner').onclick=()=>setTime(4);$('play').onclick=()=>{if(playing)return stop();if(t>=6)t=0;playing=true;last=null;$('play').textContent='Ⅱ 一時停止';raf=requestAnimationFrame(frame)};
document.querySelectorAll('[data-step]').forEach(b=>b.onclick=()=>{step=Number(b.dataset.step);document.querySelectorAll('[data-step]').forEach(btn=>{const selected=Number(btn.dataset.step)===step;btn.classList.toggle('active',selected);btn.setAttribute('aria-pressed',selected)});lesson();if(step===0&&t>4)setTime(2);if(step===1&&t<=4)setTime(5)});window.addEventListener('pagehide',stop);lesson();render();
